def _norm_col(name: Any) -> str:
    """Hive-style JDBC labels may be ``view.col`` or ``because.view.col``."""
    s = str(name)
    if "." in s:
        s = s.rsplit(".", 1)[-1]
    return s.lower()


class _JdbcChannel:
    name = "jdbc"

    def __init__(self) -> None:
        jar = os.environ.get("ZETARIS_JDBC_JAR", "")
